import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {createHash} from 'node:crypto';
import {services, industries} from '../content/services.mjs';
import {guides as preparedGuides} from '../content/guides.mjs';
import {loadGenerated} from './editorial.mjs';
const guides=[...preparedGuides,...loadGenerated().map(g=>({...g,sectionSources:g.sections.map(s=>s.sourceIndexes),sections:g.sections.map(s=>[s.heading,s.body])}))];

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const today=process.env.BUILD_DATE || new Date().toISOString().slice(0,10);
if(!/^\d{4}-\d{2}-\d{2}$/.test(today)||Number.isNaN(Date.parse(today))) throw Error('Invalid BUILD_DATE');
const origin='https://dreamprotocol.ai';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=s=>JSON.stringify(s).replace(/</g,'\\u003c');
const read=f=>fs.readFileSync(path.join(root,f),'utf8');
const write=(f,s)=>{fs.mkdirSync(path.dirname(path.join(root,f)),{recursive:true});fs.writeFileSync(path.join(root,f),s);};
const hash=f=>createHash('sha256').update(read(f)).digest('hex').slice(0,10);
const version=hash('assets/site.css');
const uiVersion=hash('assets/site.js');
const appVersion=hash('app.js');
const pages=[];
const published=guides.filter(g=>g.status==='scheduled'&&g.publishOn<=today).sort((a,b)=>b.publishOn.localeCompare(a.publishOn)||a.slug.localeCompare(b.slug));
for(const g of guides){
 if(!/^[a-z0-9-]+$/.test(g.slug)||!/^\d{4}-\d{2}-\d{2}$/.test(g.publishOn))throw Error('Invalid guide path/date');
 if(g.status==='scheduled'&&(!g.description||g.sections.length<3||!services.some(s=>s.slug===g.service)))throw Error('Incomplete scheduled guide: '+g.slug);
}
const href=slug=>{const [pathname,query]=slug.split('?');return '/'+(pathname?pathname+'/':'')+(query?'?'+query:'');};
const link=(slug,label,cls='')=>`<a${cls?` class="${cls}"`:''} href="${href(slug)}">${esc(label)}</a>`;
const button=(slug,label='Let’s talk',secondary=false)=>link(slug,label+' ↗','button'+(secondary?' secondary':''));
const eyebrow=s=>`<p class="eyebrow">${esc(s)}</p>`;
const heading=(k,h,p='')=>`<div class="section-heading">${eyebrow(k)}<h2>${h}</h2>${p?`<p>${esc(p)}</p>`:''}</div>`;
const org={'@type':'Organization','@id':origin+'/#organization',name:'Dream Protocol',legalName:'Dream Protocol',url:origin+'/',email:'hello@dreamprotocol.ai',logo:origin+'/favicon.svg',description:'AI business automation, voice agents, workflow automation, and systems integration for Bay Area businesses.',slogan:'Business, evolved.',founder:{'@type':'Person',name:'Dustin Poole'},areaServed:{'@type':'Place',name:'San Francisco Bay Area'},contactPoint:[{'@type':'ContactPoint',email:'hello@dreamprotocol.ai',contactType:'sales',areaServed:'US',availableLanguage:'English'}],knowsAbout:['AI business automation','AI voice agents','workflow automation','systems integration','APIs','Microsoft 365','CRM integration']};
function nav(active=''){
 return `<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="shell nav-wrap"><a class="brand" href="/" aria-label="Dream Protocol home"><span class="brand-mark" aria-hidden="true"></span><span>dream<span class="brand-light">protocol</span><small>BUSINESS, EVOLVED.</small></span></a><button class="menu-button" type="button" aria-expanded="false" aria-controls="primary-nav"><span class="sr-only">Open menu</span><span></span><span></span></button><nav id="primary-nav" aria-label="Primary navigation">${[['services','Services'],['industries','Industries'],['bay-area-ai-services','Bay Area'],['resources','Resources'],['pricing','Pricing'],['about','About']].map(([s,l])=>`<a href="/${s}/"${active===s?' aria-current="page"':''}>${l}</a>`).join('')}</nav><div class="nav-status" aria-hidden="true"><i></i><span>AI ONLINE</span></div>${button('contact','Automate something')}</div></header>`;
}
function footer(){return `<footer><div class="footer-glow" aria-hidden="true"></div><div class="shell"><div class="footer-command"><span><i></i>DREAMPROTOCOL SYSTEM</span><b>BUSINESS, EVOLVED.</b><span>AI / VOICE / AUTOMATION / INTEGRATION</span></div><div class="footer-top"><a class="brand" href="/"><span class="brand-mark" aria-hidden="true"></span>dream<span class="brand-light">protocol</span></a><p>Your business.<br><em>Running smarter.</em></p><a class="email-link" href="mailto:hello@dreamprotocol.ai">hello@dreamprotocol.ai ↗</a></div><div class="footer-columns"><div><h2>What we do</h2>${flagshipServices.map(s=>link(s.slug,s.name)).join('')}${link('services','All services →')}</div><div><h2>Your business</h2>${industries.map(s=>link(s.slug,s.name)).join('')}</div><div><h2>Explore</h2>${[['bay-area-ai-services','Serving the Bay Area'],['pricing','Scope & pricing'],['resources','Guides & insights'],['about','About Dream Protocol'],['security','Security & data'],['contact','Start automating']].map(([s,l])=>link(s,l)).join('')}</div><div><h2>System status</h2><p class="footer-live"><i></i> Ready to build</p><p>San Francisco Bay Area<br>Remote + onsite projects</p></div></div><div class="footer-bottom"><span>© ${today.slice(0,4)} Dream Protocol</span><span>YOUR BUSINESS → DREAM PROTOCOL → DONE</span><a href="/resources/feed.xml">RSS feed ↗</a></div></div></footer>`;}
function cta(){return `<section class="cta-band"><div class="cta-grid" aria-hidden="true"></div><div class="shell"><div>${eyebrow('READY WHEN YOU ARE')}<h2>Show us the bottleneck.<br><em>We’ll build the system.</em></h2><p>One annoying process is enough to start. Calls, follow-up, intake, handoffs, data entry, scheduling — bring the friction.</p></div><div class="cta-actions">${button('contact','Show us what to automate')}<a class="text-link" href="/#demo">Try the live AI demo ↗</a></div></div></section>`;}
const protocolBar=()=>`<div class="protocol-bar" aria-hidden="true"><div class="shell"><span>AI BUSINESS AUTOMATION</span><span class="protocol-live"><i></i>SYSTEM ONLINE</span><span>VOICE · LEADS · SCHEDULING · WORKFLOWS · DOCUMENTS · KNOWLEDGE</span></div></div>`;
const stackSection=()=>`<section class="section stack-section"><div class="shell">${heading('REAL TOOLS. ONE WORKING SYSTEM.','The stack should disappear.<br><em>The outcome should not.</em>','Dream Protocol uses proven AI, cloud, voice, business, and integration tools instead of forcing every workflow into one vendor.')}<div class="stack-grid">${['OpenAI / model APIs','Vapi / voice AI','Microsoft 365 / Graph','Google Workspace','Salesforce & CRM platforms','QuickBooks & accounting','Python / REST APIs','Webhooks & business systems','Calendars & scheduling','Business phone systems','SharePoint / OneDrive','Custom integrations'].map((x,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><strong>${x}</strong></div>`).join('')}</div><p class="section-note">The exact stack is chosen around the workflow. Vendor features, API access, licensing, security requirements, and data handling are confirmed before anything is promised.</p></div></section>`;
const outcomesSection=()=>`<section class="section shell outcomes-section">${heading('MEASURE THE BUSINESS RESULT','If it works, you should<br><em>be able to see it.</em>','We define the operational metric before launch so the automation has something more useful than “AI is cool” to prove.')}<div class="outcome-grid">${[['Response time','How quickly a caller, lead, or request gets a useful first response.'],['Missed opportunities','Calls, leads, bookings, or follow-ups that no longer disappear into a queue.'],['Admin time','Repeated typing, routing, searching, and status work removed from the team.'],['Cycle time','How long a quote, document, request, booking, or handoff takes to reach the next step.'],['Exception rate','How often the system needs human rescue and where the workflow needs tuning.'],['Adoption','Whether the people using the system actually trust it enough to keep using it.']].map(([h,p],i)=>`<article><span>0${i+1}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></section>`;
const popularAutomationSection=()=>`<section class="section pale-section popular-automation"><div class="shell">${heading('WHAT COMPANIES KEEP ASKING FOR','The repeated work<br><em>worth attacking first.</em>','These are common starting points because they are easy to recognize, measurable, and tied directly to revenue or staff time.')}<div class="popular-grid">${[['Missed-call recovery','Answer after hours, capture context, route urgency, and trigger follow-up.'],['Lead response & nurture','Respond fast, qualify, follow up, update CRM, and alert sales.'],['Appointment booking','Check rules, request or book time, send confirmation, and handle exceptions.'],['Quote & proposal follow-up','Track sent quotes, remind customers, create tasks, and flag hot opportunities.'],['Inbox triage','Classify inbound email, extract requests, route ownership, and prepare responses.'],['Invoice & document processing','Extract data, validate fields, route low-confidence cases, and create the next record.'],['CRM updates','Turn forms, calls, email, and meetings into cleaner customer records without retyping.'],['Internal knowledge','Answer staff questions from approved policies, SOPs, manuals, and documents with source references.']].map(([h,p])=>`<article><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></div></section>`;

function layout(slug,title,description,body,{active='',schema=[],crumbs=[],home=false,article=false,noindex=false}={}){
 const url=origin+href(slug);
 const breadcrumb=crumbs.length?[{'@type':'BreadcrumbList',itemListElement:[{name:'Home',item:origin+'/'},...crumbs.map(([s,n])=>({name:n,item:origin+href(s)}))].map((x,i)=>({'@type':'ListItem',position:i+1,...x}))}]:[];
 const graph=[org,{'@type':'WebSite','@id':origin+'/#website',name:'Dream Protocol',url:origin+'/'},{'@type':'WebPage','@id':url+'#webpage',url,name:title,description,isPartOf:{'@id':origin+'/#website'},about:{'@id':origin+'/#organization'}},...breadcrumb,...schema];
 const html=`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} | Dream Protocol</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${url}">${noindex?'<meta name="robots" content="noindex">':''}<meta name="theme-color" content="#101717"><meta property="og:type" content="${article?'article':'website'}"><meta property="og:title" content="${esc(title)} | Dream Protocol"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${url}"><meta property="og:image" content="${origin}/public/dream-protocol-abstract.webp"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="alternate" type="application/rss+xml" title="Dream Protocol guides" href="/resources/feed.xml"><link rel="stylesheet" href="/assets/site.css?v=${version}"><script defer src="/attribution.js"></script><script defer src="/assets/site.js?v=${uiVersion}"></script>${home?`<script>window.DREAMPROTOCOL_CONFIG={businessAnalysisEndpoint:"https://api.dreamprotocol.ai/analyze-business",vapiPublicKey:"ec40770e-0ff1-482c-929e-5288315e24b1",vapiAssistantId:"30ccf544-cd70-4ba6-8b23-fcd9ff5a4fec"};</script><script defer src="/app.js?v=${appVersion}"></script>`:''}<script type="application/ld+json">${json({'@context':'https://schema.org','@graph':graph})}</script></head>
<body data-page="${esc(slug||'home')}"${home?' data-home="true"':''}>${nav(active)}${home?'':protocolBar()}<main id="main">${body}</main>${footer()}</body></html>\n`;
 if(!noindex)pages.push({slug,url});
 write(slug?slug+'/index.html':'index.html',html);
}
const crumbs=(items)=>`<div class="shell breadcrumbs"><a href="/">Home</a>${items.map(([s,n],i)=>`<span aria-hidden="true">/</span>${i===items.length-1?`<span>${esc(n)}</span>`:link(s,n)}`).join('')}</div>`;
const serviceCard=(s,i)=>`<a href="/${s.slug}/" class="service-card service-${s.slug}" data-service="${esc(s.slug)}"><div class="service-card-visual" aria-hidden="true"><span class="service-gridline"></span><span class="service-orbit"><i></i><b>${s.icon}</b></span><span class="service-pulse"><i></i><i></i><i></i></span><small>DP / ${esc(s.name).toUpperCase()}</small></div><div class="service-card-body"><div class="card-top"><span class="card-number">${String(i+1).padStart(2,'0')}</span><span class="service-arrow" aria-hidden="true">↗</span></div><p class="eyebrow">${esc(s.tag)}</p><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><div class="card-price">${esc(s.price)} <span>${esc(s.unit)}</span></div></div></a>`;
const flagshipServices=services.slice(0,6);
const supportServices=services.slice(6);
const homeServices=['ai-front-desk','ai-lead-engine','workflow-automation'].map(slug=>services.find(s=>s.slug===slug));

const industryCards=()=>`<div class="industry-grid">${industries.map((s,i)=>`<a href="/${s.slug}/" class="industry-card"><span>0${i+1}</span><h3>${esc(s.name)}</h3><span aria-hidden="true">↗</span></a>`).join('')}</div>`;
const guideCard=g=>`<a class="guide-card" href="/resources/${g.slug}/"><div class="guide-art art-${g.service}" aria-hidden="true"><span>${services.find(s=>s.slug===g.service)?.icon||'↗'}</span></div><div class="guide-copy"><p class="eyebrow">${esc(g.category)} <span> / GUIDE</span></p><h3>${esc(g.title)}</h3><p>${esc(g.description)}</p><span class="text-link">Read the guide ↗</span></div></a>`;
const faq=items=>`<section class="shell section faq-section">${heading('A little more clarity','Questions, answered.')}<div>${items.map(([q,a])=>`<details><summary>${esc(q)}<span aria-hidden="true">+</span></summary><p>${esc(a)}</p></details>`).join('')}</div></section>`;
const processSection=()=>`<section id="implementation" class="section shell">${heading('HOW IT GOES LIVE','From friction.<br>To finished.','A direct path from the thing wasting your time to a system doing the work.')}<div class="process-grid">${[['01','Find the drag','Map the repeated work, handoffs, systems, and places your team loses time.'],['02','Design the system','Define the AI, integrations, guardrails, escalation points, and the outcome it must deliver.'],['03','Make it real','Build it, connect it, test real scenarios, and tune it against the way your business actually operates.'],['04','Keep it sharp','Measure what works, improve the weak spots, and expand only where the automation earns its keep.']].map(([n,t,p])=>`<article><span>${n}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section>`;
const regional=()=>`<section class="regional section"><div class="shell regional-grid"><div>${eyebrow('Built for the Bay Area')}<h2>Big possibilities.<br><em>Local understanding.</em></h2><p>From a neighborhood shop to a growing operations team. We help businesses across the San Francisco Bay Area turn AI into useful, everyday work.</p>${button('bay-area-ai-services','Explore Bay Area services',true)}</div><div class="region-visual"><span class="region-stamp">37.7749° N &nbsp; 122.4194° W</span><div class="region-orbit" aria-hidden="true"><i></i><i></i><i></i><b>DP</b></div><div class="region-names"><span>San Francisco</span><span>Peninsula</span><span>South Bay</span><span>East Bay</span><span>North Bay</span></div><small>Serving all nine Bay Area counties</small></div></div></section>`;

const architectureSection=()=>`<section class="architecture-section section"><div class="architecture-ambient" aria-hidden="true"></div><div class="shell architecture-grid"><div class="architecture-copy">${eyebrow('THE DIFFERENCE / SYSTEMS THINKING')}<h2>The AI is one layer.<br><em>The whole business has to work.</em></h2><p>Dream Protocol brings practical experience across business IT, infrastructure, cloud, voice, APIs, automation, and integration. We design the handoff around the systems and people you already depend on.</p>${link('about','Why that background matters ↗','text-link')}<div class="architecture-proof"><span>VOICE</span><span>IDENTITY</span><span>APIs</span><span>M365</span><span>CRM</span><span>HUMANS</span></div></div><div class="architecture-console"><div class="architecture-console-head"><span><i></i>DREAMPROTOCOL / ORCHESTRATION MAP</span><b>SYSTEM ONLINE</b></div><div class="architecture-map" aria-label="Illustrative map of a production automation system"><div class="architecture-gridlines" aria-hidden="true"></div><div class="arch-node arch-input"><span>01</span><strong>INPUT</strong><small>Phone · form · email</small></div><div class="arch-node arch-knowledge"><span>02</span><strong>KNOWLEDGE</strong><small>Approved business context</small></div><div class="arch-node arch-systems"><span>03</span><strong>SYSTEMS</strong><small>CRM · calendar · M365</small></div><div class="arch-node arch-action"><span>04</span><strong>ACTION</strong><small>Route · update · notify</small></div><div class="arch-node arch-follow"><span>05</span><strong>FOLLOW-UP</strong><small>SMS · email · task</small></div><div class="arch-node arch-human"><span>06</span><strong>HUMAN</strong><small>Exceptions · judgment</small></div><div class="arch-core"><i class="arch-ring ring-a"></i><i class="arch-ring ring-b"></i><span>DP</span><small>ORCHESTRATION</small></div><i class="arch-beam beam-a"></i><i class="arch-beam beam-b"></i><i class="arch-beam beam-c"></i><i class="arch-beam beam-d"></i></div><div class="architecture-ledger"><div><span>OBSERVE</span><b>Understand the request</b></div><div><span>DECIDE</span><b>Apply rules + context</b></div><div><span>ACT</span><b>Move the work forward</b></div><div><span>ESCALATE</span><b>Keep judgment human</b></div></div><p class="architecture-note">Most demos stop at the conversation. Production work includes permissions, business rules, API behavior, error handling, testing, monitoring, and a clear human fallback.</p></div></div></section>`;

const productionTrustSection=()=>`<section class="section production-trust"><div class="shell"><div class="section-heading split"><div>${eyebrow('BUILT FOR PRODUCTION, NOT THEATER')}<h2>Useful automation.<br><em>With boundaries.</em></h2></div><div><p>We do not pretend a clever demo is the finished system. Production starts with approved knowledge, explicit permissions, tested exceptions, and a metric the business can actually watch.</p>${link('security','See our security & data approach ↗','text-link')}</div></div><div class="production-grid">${[['01','Approved knowledge','Define what the AI is allowed to know and say.'],['02','Controlled access','Use the minimum permissions and data required for the job.'],['03','Human escalation','Keep unusual, sensitive, or judgment-heavy work with a person.'],['04','Measured outcome','Track response time, missed opportunities, admin time, cycle time, and exception rate.']].map(([n,h,p])=>`<article class="production-card"><span>${n}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></div></section>`;

const credibilitySection=()=>`<section class="section credibility-section" id="proof"><div class="shell"><div class="credibility-heading"><div>${eyebrow('SELECTED DELIVERY / REAL SCALE')}<h2>Built in the real world.<br><em>Not just in a demo.</em></h2></div><p>Dream Protocol is backed by hands-on delivery across AI, cloud, Microsoft 365, endpoint, data, voice, infrastructure, and business systems. The examples below are anonymized, but the scale is real.</p></div><div class="delivery-metrics" aria-label="Selected delivery scale"><div><strong>25 TB</strong><span>enterprise data migration architecture</span></div><div><strong>15</strong><span>concurrent users on Azure Virtual Desktop</span></div><div><strong>1.5 TB</strong><span>production accounting and application data</span></div><div><strong>60–75%</strong><span>less targeted manual administrative work</span></div></div><div class="proof-grid proof-grid-six"><article class="proof-card proof-live"><div class="proof-status"><i></i><span>AI + VOICE</span></div><span class="proof-number">01</span><h3>Front-desk automation</h3><p>Voice agents built for intake, scheduling, callback capture, structured summaries, business rules, and human escalation instead of a generic chatbot script.</p><div class="proof-result"><b>OUTCOME</b><span>routine work handled before it reaches staff</span></div></article><article class="proof-card"><div class="proof-status"><i></i><span>CLOUD + DATA</span></div><span class="proof-number">02</span><h3>25 TB data modernization</h3><p>Designed a multi-site cloud file migration for a large engineering/GIS data estate, including local cache, archival strategy, access, and operating model.</p><div class="proof-result"><b>SCALE</b><span>approximately 25 TB</span></div></article><article class="proof-card"><div class="proof-status"><i></i><span>AZURE</span></div><span class="proof-number">03</span><h3>Production virtual desktop</h3><p>Architected Azure Virtual Desktop for accounting and tax workloads with identity, profile management, application compatibility, and business continuity in the design.</p><div class="proof-result"><b>SCALE</b><span>~15 concurrent users · ~1.5 TB data</span></div></article><article class="proof-card"><div class="proof-status"><i></i><span>AUTOMATION</span></div><span class="proof-number">04</span><h3>Manual work cut dramatically</h3><p>Selected automation programs replaced repetitive administrative steps across intake, provisioning, support, reporting, and workflow execution.</p><div class="proof-result"><b>MEASURED</b><span>~60–75% reduction in targeted manual admin work</span></div></article><article class="proof-card"><div class="proof-status"><i></i><span>DEPLOYMENT</span></div><span class="proof-number">05</span><h3>Faster standardized delivery</h3><p>Repeatable provisioning, templates, scripting, and operating procedures turned one-off deployment work into a controlled delivery process.</p><div class="proof-result"><b>MEASURED</b><span>3–5× faster standardized deployments</span></div></article><article class="proof-card proof-building"><div class="proof-status"><i></i><span>PRODUCT</span></div><span class="proof-number">06</span><h3>DreamProtocol Command</h3><p>One workspace for agents, workflows, activity, connections, client administration, usage, and platform health. The control layer now being built behind the service model.</p><div class="proof-result"><b>STATUS</b><span>in development</span></div></article></div><p class="proof-disclosure">Selected examples are anonymized delivery experience behind Dream Protocol. Metrics are shown only where they have been measured or documented; illustrative product screens are labeled as such.</p></div></section>`;

const founderProofSection=()=>`<section class="section founder-proof-section"><div class="shell founder-proof-grid"><div class="founder-proof-photo"><img src="/public/logos/customers/dustin-poole-about.png" width="1200" height="1200" alt="Dustin Poole, founder of Dream Protocol" loading="lazy"><div class="founder-photo-label"><span>FOUNDER / DREAM PROTOCOL</span><b>DUSTIN POOLE</b></div></div><div class="founder-proof-copy">${eyebrow('FOUNDER-LED / BUILT HANDS-ON')}<h2>The person building it<br><em>is in the room.</em></h2><p class="founder-lead">Dream Protocol is founder-led by Dustin Poole and built around a simple standard: the technology has to survive contact with the real business.</p><p>The work combines AI with practical systems thinking across cloud, voice, identity, APIs, automation, integration, and the human handoffs that make a workflow actually usable.</p><div class="founder-principles"><span>DESIGN THE WORK</span><span>BUILD THE SYSTEM</span><span>CONNECT THE STACK</span><span>KEEP IT OPERABLE</span></div>${link('about','Meet Dream Protocol ↗','text-link')}</div></div></section>`;

const platformPreviewSection=()=>`<section class="section platform-preview" id="command-preview"><div class="platform-ambient" aria-hidden="true"></div><div class="shell platform-grid"><div class="platform-copy">${eyebrow('PRODUCT DIRECTION / IN DEVELOPMENT')}<div class="platform-status"><i></i><span>BUILDING DREAMPROTOCOL COMMAND</span></div><h2>One place to run<br><em>the AI operation.</em></h2><p>Today, Dream Protocol builds and operates automations around the systems a business already uses. The next layer is DreamProtocol Command: a single web workspace for agents, workflows, activity, connections, analytics, and client administration.</p><p class="platform-note">This is product direction, not a claim that the full platform is already shipping.</p>${button('contact','Build with Dream Protocol')}</div><div class="platform-window" aria-label="Illustrative DreamProtocol Command product direction"><div class="platform-window-head"><span><i></i>DREAMPROTOCOL / COMMAND</span><b>IN DEVELOPMENT</b></div><div class="platform-sidebar" aria-hidden="true"><strong>DP</strong><span class="active">Overview</span><span>Agents</span><span>Workflows</span><span>Activity</span><span>Connections</span><span>Clients</span></div><div class="platform-main" aria-hidden="true"><div class="platform-title"><span>OPERATIONS OVERVIEW</span><b>ALL SYSTEMS</b></div><div class="platform-kpis"><div><small>AGENTS</small><strong>12</strong><span>illustrative</span></div><div><small>WORKFLOWS</small><strong>28</strong><span>illustrative</span></div><div><small>CONNECTIONS</small><strong>9</strong><span>illustrative</span></div></div><div class="platform-feed"><div><span>VOICE</span><b>Front desk agent</b><em>Completed</em></div><div><span>LEAD</span><b>Qualification workflow</b><em>Routed</em></div><div><span>M365</span><b>Follow-up task</b><em>Created</em></div><div><span>HUMAN</span><b>Exception review</b><em>Waiting</em></div></div><div class="platform-admin"><span>CLIENT ADMIN</span><b>Tenants · usage · health · deployments</b></div></div></div></div></section>`;

// Homepage: one focused narrative. Detail pages carry the depth.
layout('','AI Business Automation for Bay Area Businesses','AI business automation that answers calls, captures leads, books appointments, connects systems, and handles repetitive work for Bay Area businesses.',`
<section class="home-hero dp-wow" id="top"><div class="hero-aurora" aria-hidden="true"></div><div class="hero-noise" aria-hidden="true"></div><div class="shell hero-grid"><div class="hero-copy">${eyebrow('AI BUSINESS AUTOMATION / LIVE')}<h1>Put repetitive work<br><em>on autopilot.</em></h1><p class="hero-intro">Calls answered. Leads captured. Appointments booked.<br>Follow-ups sent. Systems updated. Automatically.</p><p class="hero-sub">Dream Protocol connects AI to the phones, Microsoft 365, CRM, calendar, APIs, and workflows you already run. The point is not another AI tool. The point is work getting done.</p><div class="hero-actions"><a class="button hero-primary" href="#demo">Scan my business <span>↗</span></a><a class="text-link hero-secondary" href="/contact/">Find my automation opportunities <span>↗</span></a></div><div class="hero-footnote"><span class="status-dot"></span> BAY AREA · PRODUCTION SYSTEMS · VOICE · WORKFLOWS · INTEGRATIONS</div></div><div class="hero-cockpit automation-core" aria-label="Illustrative Dream Protocol automation command center"><div class="core-head"><span><i class="status-dot"></i>DREAMPROTOCOL / COMMAND</span><b>SYSTEM MODEL</b></div><div class="cockpit-meta" aria-hidden="true"><span>BUSINESS INPUT</span><span>AI ORCHESTRATION</span><span>ACTION LAYER</span></div><div class="cockpit-main"><div class="core-stage" aria-hidden="true"><span class="core-coordinate coordinate-a">37.77°N</span><span class="core-coordinate coordinate-b">122.41°W</span><i class="core-ring ring-one"></i><i class="core-ring ring-two"></i><i class="core-ring ring-three"></i><i class="core-axis axis-x"></i><i class="core-axis axis-y"></i><div class="core-mark"><span>DP</span><small>AI CORE</small></div><span class="signal-node signal-voice">VOICE</span><span class="signal-node signal-web">WEB</span><span class="signal-node signal-crm">CRM</span><span class="signal-node signal-m365">M365</span></div><div class="cockpit-feed"><div class="cockpit-feed-title"><span>LIVE ORCHESTRATION</span><i></i></div><div class="event-feed"><div class="event-row"><span>01</span><b>INCOMING CALL</b><em>AI answers</em></div><div class="event-row"><span>02</span><b>NEW LEAD</b><em>Qualified</em></div><div class="event-row"><span>03</span><b>CALENDAR</b><em>Next step ready</em></div><div class="event-row"><span>04</span><b>CRM</b><em>Context prepared</em></div><div class="event-row"><span>05</span><b>FOLLOW-UP</b><em>Workflow continues</em></div></div></div></div><div class="cockpit-status" aria-hidden="true"><div><span>01</span><b>LISTEN</b><small>Calls · forms · inbox</small></div><div><span>02</span><b>UNDERSTAND</b><small>Intent · rules · context</small></div><div><span>03</span><b>CONNECT</b><small>CRM · calendar · APIs</small></div><div><span>04</span><b>ACT</b><small>Route · update · follow up</small></div></div><div class="core-foot"><span>YOUR BUSINESS</span><b>→</b><span>DREAM PROTOCOL</span><b>→</b><span>DONE</span></div></div></div><a class="demo-float-cta" href="#demo">SCAN YOUR BUSINESS <span>↗</span></a></section>
<div class="principles-strip dp-outcome-strip"><div class="shell"><span>ANSWER CALLS</span><span>QUALIFY LEADS</span><span>CONNECT SYSTEMS</span><span>FOLLOW UP 24/7 ↗</span></div></div>
<section class="home-trust-rail" aria-label="Dream Protocol delivery principles"><div class="shell"><div><b>BAY AREA BASED</b><small>Remote + onsite</small></div><div><b>PRODUCTION EXPERIENCE</b><small>Cloud · voice · data · AI</small></div><div><b>WORKS WITH YOUR STACK</b><small>APIs · M365 · CRM · voice</small></div><div><b>HUMAN ESCALATION</b><small>Exceptions stay visible</small></div><div><b>ONGOING SUPPORT</b><small>Monitor · tune · improve</small></div></div></section>
<section class="demo-section section dp-demo-priority" id="demo"><div class="demo-backdrop" aria-hidden="true"></div><div class="shell demo-grid"><div class="demo-copy">${eyebrow('01 / LIVE BUSINESS SCAN')}<h2>Your business.<br><em>Turned into a working demo.</em></h2><p>Paste your website. Dream Protocol learns the public business details, builds a first-pass AI front desk, and surfaces practical automation ideas based on what it finds.</p><p class="small-copy">Then start a live voice conversation. Production deployments add approved knowledge, business rules, integrations, monitoring, and human escalation.</p>${link('ai-front-desk','See how the production front desk works ↗','text-link')}<div class="demo-copy-rail" aria-hidden="true"><span><b>01</b> SCAN</span><span><b>02</b> BUILD</span><span><b>03</b> TALK</span><span><b>04</b> AUTOMATE</span></div></div><div class="demo-window demo-command-center"><div class="window-bar"><span><i></i><i></i><i></i></span><small>DREAM PROTOCOL / LIVE BUSINESS SCAN</small><span>↗</span></div><div class="demo-mode-rail" aria-hidden="true"><span>PUBLIC WEBSITE INTELLIGENCE</span><b>SCAN → AGENT → OPPORTUNITIES</b></div>${read('content/partials/demo.html')}<div class="demo-bottom">AI receptionist from $399/month <span>Setup from $995</span></div></div></div></section>
<section class="recording-stage section" id="recording"><div class="recording-ambient" aria-hidden="true"></div><div class="shell recording-stage-grid"><div class="recording-copy">${eyebrow('02 / HEAR IT IN ACTION')}<h2>Don’t just read about it.<br><em>Hear the experience.</em></h2><p>This recorded example shows the feel of a Dream Protocol front desk conversation: natural greeting, routine question handling, clear context capture, and a clean path back to a person when needed.</p><div class="recording-points"><span>Natural conversation</span><span>Business-aware answers</span><span>Human handoff</span></div></div><div class="recording-console"><div class="recording-console-head"><span><i></i>DREAMPROTOCOL / RECORDED EXAMPLE</span><b>VOICE</b></div><div class="recording-main"><div class="recording-orb" aria-hidden="true"><i></i><i></i><i></i><b>DP</b></div><div class="recording-details"><p class="eyebrow">MEDICAL FRONT DESK / ILLUSTRATIVE</p><h3>Sample AI front-desk conversation</h3><p>Recorded example for demonstration. Production agents are configured around each business’s approved knowledge, call flow, and escalation rules.</p></div></div><div class="audio-card recording-audio-card"><div class="audio-wave" aria-hidden="true">${Array.from({length:40},(_,i)=>'<i style="--h:'+(18+(i*43)%70)+'px"></i>').join('')}</div><audio controls preload="none" aria-label="Recorded Dream Protocol front-desk example"><source src="/demo-audio/dreamprotocol-medical-demo.mp3" type="audio/mpeg"></audio></div><div class="recording-flow" aria-hidden="true"><span>CALL</span><b>→</b><span>UNDERSTAND</span><b>→</b><span>ANSWER</span><b>→</b><span>HANDOFF</span></div></div></div></section>
${credibilitySection()}
<section class="section shell flagship-section" id="services"><div class="section-heading split"><div>${eyebrow('02 / THREE WAYS TO START')}<h2>Revenue protected.<br><em>Busywork removed.</em></h2></div><div><p>Start where the drag is obvious: missed calls, slow lead response, or repetitive work bouncing between people and systems. We can expand after the first automation earns its keep.</p>${link('services','See every Dream Protocol service ↗','text-link')}</div></div><div class="service-grid home-service-grid">${homeServices.map(serviceCard).join('')}</div></section>
${architectureSection()}
${productionTrustSection()}
${platformPreviewSection()}
<section class="manifesto-band"><div class="shell"><p>AI should disappear into the work.</p><span>Not another dashboard. Not another thing to babysit. A system that quietly keeps the business moving.</span></div></section>
${processSection()}
<section class="section shell price-preview cinematic-pricing" id="pricing"><div>${eyebrow('VISIBLE ENTRY POINTS. REAL SCOPE.')}<h2>Know where it starts.<br><em>Then build what matters.</em></h2></div><div><p>AI reception starts at $399/month. Lead automation starts at $499/month. Workflow automation starts at $1,500. More complex integrations get a defined scope before you commit.</p>${button('pricing','See all starting prices',true)}</div></section>
<section class="contact-section section cinematic-contact" id="contact"><div class="contact-ambient" aria-hidden="true"></div><div class="shell contact-grid"><div class="contact-copy">${eyebrow('YOUR BUSINESS → DREAM PROTOCOL → DONE')}<h2>Show us the process<br><em>you are tired of doing.</em></h2><p>One annoying workflow is enough to start. We will map what should be automated, what should stay human, and how it connects to the systems you already use.</p><a href="mailto:hello@dreamprotocol.ai" class="text-link">hello@dreamprotocol.ai ↗</a><div class="contact-path" aria-hidden="true"><span>INPUT</span><b>→</b><span>AI + RULES</span><b>→</b><span>SYSTEMS</span><b>→</b><span>DONE</span></div></div>${read('content/partials/contact.html')}</div></section>`,{home:true});

layout('services','AI Automation Services for Bay Area Businesses','Explore AI receptionists, lead response, scheduling and dispatch, workflow automation, document processing, knowledge agents, integrations, training, and custom AI builds.',`${crumbs([['services','Services']])}<section class="page-hero shell">${eyebrow('OUTCOMES FIRST. TECHNOLOGY SECOND.')}<h1>AI that actually<br><em>does the work.</em></h1><p>Answer calls. Respond to leads. Book work. Process documents. Find internal answers. Move data. Start with the business pain, then build the system around it.</p><div class="actions"><a class="button" href="/#demo">Try the live receptionist demo ↗</a>${link('contact','Show us what wastes time ↗','text-link')}</div></section><section class="shell section compact">${heading('FLAGSHIP AUTOMATIONS','The work companies<br><em>want off their plate.</em>','Clear business outcomes, visible starting prices, and a defined path to launch.')}<div class="service-grid">${flagshipServices.map(serviceCard).join('')}</div></section><section class="section pale-section"><div class="shell">${heading('BUILD, CONNECT & KEEP IT RUNNING','The capabilities<br><em>behind the automation.</em>','Integrations, training, ongoing operations, and custom builds support the systems above or stand on their own.')}<div class="service-grid">${supportServices.map((s,i)=>serviceCard(s,i+flagshipServices.length)).join('')}</div></div></section>${stackSection()}${outcomesSection()}${processSection()}${cta()}`,{active:'services',crumbs:[['services','Services']]});

for(const s of services){
 const guide=published.find(g=>g.service===s.slug)||published.find(g=>g.slug===s.guide);
 layout(s.slug,s.title,s.description,`${crumbs([['services','Services'],[s.slug,s.name]])}<section class="page-hero shell detail-hero"><div>${eyebrow(s.name+' / BAY AREA')}<h1>${esc(s.headline).replace('\n','<br>')}</h1><p>${esc(s.description)}</p><div class="actions">${button('contact','Automate this workflow')}${s.slug==='ai-front-desk'?'<a class="text-link" href="/#demo">Try the live demo ↗</a>':link('pricing','View scope & pricing ↗','text-link')}</div></div><div class="detail-art"><img src="/public/${s.image}" alt="" width="1536" height="1024"><span>${esc(s.tag)} / Dream Protocol</span></div></section><section class="section shell detail-intro"><div>${eyebrow('A practical starting point')}<h2>${esc(s.name)}.<br><em>Built around your work.</em></h2></div><p>${esc(s.intro)}</p></section><section class="section pale-section"><div class="shell"><div class="three-grid">${s.points.map(([h,p],i)=>`<article class="feature"><span class="step-number">0${i+1}</span><h2>${esc(h)}</h2><p>${esc(p)}</p></article>`).join('')}</div></div></section><section class="section shell example-grid"><div class="example-panel">${eyebrow('An illustrative workflow')}<h2>${esc(s.example[0])}</h2><p>${esc(s.example[1])}</p><div class="mini-flow"><span>Context</span><b>→</b><span>Clear rules</span><b>→</b><span>Next step</span></div><small>Example only. The final workflow is agreed with your team.</small></div><div class="scope-panel">${eyebrow('What’s included')}<h2>${esc(s.price)} <small>${esc(s.unit)}</small></h2><p>${esc(s.setup)}</p><ul class="check-list">${s.deliverables.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="small-copy">Software licenses, third-party usage, custom APIs, data cleanup, and additional scope are quoted separately where needed.</p>${button('contact','Build my starting point')}</div></section>${faq(s.faqs)}<section class="section shell related-section">${heading('The next useful connection','Build on your next step.')}<div class="related-grid">${s.related.map(x=>services.find(v=>v.slug===x)).map(serviceCard).join('')}${guide?guideCard(guide):`<a class="related-note" href="/industries/"><span class="eyebrow">YOUR BUSINESS</span><h3>See how it fits your industry.</h3><p>Explore the intake, training, and workflow ideas relevant to your team.</p><span>Explore industries ↗</span></a>`}</div></section>${cta()}`,{active:'services',crumbs:[['services','Services'],[s.slug,s.name]],schema:[{'@type':'Service',name:s.name,description:s.description,url:origin+href(s.slug),provider:{'@id':origin+'/#organization'},areaServed:org.areaServed}]});
}

layout('industries','AI for Every Kind of Bay Area Business','Explore practical AI workflows for Bay Area service teams, professional firms, accounting offices, retailers, property teams, and more.',`${crumbs([['industries','Industries']])}<section class="page-hero shell">${eyebrow('YOUR BUSINESS, YOUR WORKFLOW')}<h1>Your business has a rhythm.<br><em>AI should learn it.</em></h1><p>We build around your calls, customers, handoffs, tools, rules, and exceptions — not around a generic AI template.</p></section><section class="section shell compact">${industryCards()}<div class="wide-note"><h2>Your industry isn’t the limit.</h2><p>Startups, nonprofits, education teams, and other businesses are welcome. Bring a repeated task, a training need, or an idea.</p>${button('contact','Tell us about your business',true)}</div></section>${regional()}${cta()}`,{active:'industries',crumbs:[['industries','Industries']]});
for(const s of industries){layout(s.slug,s.title,s.description,`${crumbs([['industries','Industries'],[s.slug,s.name]])}<section class="page-hero shell">${eyebrow(s.name+' / BAY AREA')}<h1>${esc(s.headline).replace('\n','<br>')}</h1><p>${esc(s.need)}</p><div class="actions">${button('contact','Show us your workflow')}${link(s.primary,'Explore '+services.find(x=>x.slug===s.primary).name.toLowerCase()+' ↗','text-link')}</div></section><section class="section pale-section"><div class="shell">${heading('Where to begin','Make the next step clearer.')}<div class="three-grid">${s.steps.map(([t,p],i)=>`<article class="feature"><span class="step-number">0${i+1}</span><h3>${esc(t)}</h3><p>${esc(p)}</p></article>`).join('')}</div></div></section><section class="section shell"><div class="wide-note">${eyebrow('ILLUSTRATIVE EXAMPLE')}<h2>What it could look like.</h2><p>${esc(s.example)}</p><small>Example only. Your systems, requirements, and approved process shape the implementation.</small></div></section>${faq([s.faq,['Do you serve our part of the Bay Area?','We serve businesses across San Francisco, San Mateo, Santa Clara, Alameda, Contra Costa, Marin, Sonoma, Napa, and Solano counties. Start remotely; onsite delivery is quoted separately.']])}<section class="section shell">${heading('The services behind the workflow','Build my starting point.')}<div class="two-grid">${[s.primary,s.secondary].map(x=>services.find(v=>v.slug===x)).map(serviceCard).join('')}</div></section>${cta()}`,{active:'industries',crumbs:[['industries','Industries'],[s.slug,s.name]]});}

layout('bay-area-ai-services','AI Automation Services Across the San Francisco Bay Area','AI reception, lead response, scheduling, workflow automation, document processing, knowledge agents, integrations, training, and custom AI across the Bay Area. Explore services for your business and start a conversation.',`${crumbs([['bay-area-ai-services','Bay Area']])}<section class="page-hero shell">${eyebrow('ALL NINE COUNTIES. EVERY KIND OF BUSINESS.')}<h1>Bay Area speed.<br><em>AI that keeps up.</em></h1><p>AI systems for the businesses that keep the Bay Area moving. Faster response, cleaner handoffs, connected tools, and less repetitive work.</p><div class="actions">${button('contact','Talk about your business')}${link('services','Explore our services ↗','text-link')}</div></section>${regional()}<section class="section shell">${heading('Across the region','One connected Bay Area.','Start with a remote conversation. Onsite workshops and project work are quoted for your location and scope.')}<div class="region-grid">${[['San Francisco','San Francisco County','Customer inquiries, team training, and connected back-office work for businesses throughout the city.'],['The Peninsula','San Mateo County','Practical workflows for office teams, independent firms, and local service businesses.'],['South Bay','Santa Clara County','Training and integration projects for growing teams, shops, and service operations.'],['East Bay','Alameda & Contra Costa counties','Clearer intake and handoffs for teams working across communities and service areas.'],['North Bay','Marin, Sonoma, Napa & Solano counties','Business information, inquiry routing, and practical automation for local teams.']].map(([n,c,p])=>`<article class="region-card">${eyebrow(c)}<h3>${n}</h3><p>${p}</p></article>`).join('')}</div><p class="section-note">These are service areas. Project delivery and onsite availability are agreed during scoping.</p></section><section class="section pale-section"><div class="shell">${heading('Your business belongs here','A practical fit.<br>Across industries.')} ${industryCards()}</div></section>${faq([['Do you work with businesses outside technology?','Yes. We work across industries, including local shops, professional offices, contractors, hospitality, and property teams. The task and requirements determine the project.'],['Do we need to replace our software?','We start by reviewing the systems you already use. Integration depends on the APIs, permissions, and licenses available. We discuss any required changes before agreeing on scope.'],['Can our first step be a workshop?','Yes. The starting workshop is a two-hour remote session for up to five people at $750, with a prompt guide and one 30-minute follow-up. Onsite delivery and larger groups are quoted separately.']])}${cta()}`,{active:'bay-area-ai-services',crumbs:[['bay-area-ai-services','Bay Area']]});

layout('pricing','AI Automation Pricing & Starting Costs','See Dream Protocol starting prices for AI receptionists, lead response, scheduling, workflow automation, document processing, knowledge agents, integrations, training, managed operations, and custom AI.',`${crumbs([['pricing','Pricing']])}<section class="page-hero shell">${eyebrow('VISIBLE ENTRY POINTS. SCOPED DELIVERY.')}<h1>Start small.<br><em>Know what it costs.</em></h1><p>We publish useful starting prices where the work can be productized. Complex integrations and custom builds still get a real scope before you commit, not a made-up flat fee.</p></section><section class="section shell compact">${heading('FLAGSHIP AUTOMATIONS','Start with the outcome.','These are the services most businesses can recognize immediately. Pricing shown is the starting point for the published scope.')}<div class="pricing-grid">${flagshipServices.map(s=>`<article class="price-card">${eyebrow(s.tag)}<h2>${esc(s.name)}</h2><div class="price">${esc(s.price)}<small>${esc(s.unit)}</small></div><p>${esc(s.setup)}</p><ul class="check-list">${s.deliverables.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${button('contact?service='+encodeURIComponent(s.name),'Price my workflow')}${link(s.slug,'Explore the service ↗','text-link')}</article>`).join('')}</div></section><section class="section pale-section"><div class="shell">${heading('ENABLE, EXTEND & SUPPORT','The work behind the work.','Systems integration, training, ongoing AI operations, and custom builds vary more by environment, so we price the entry point and scope the rest.')}<div class="pricing-grid">${supportServices.map(s=>`<article class="price-card">${eyebrow(s.tag)}<h2>${esc(s.name)}</h2><div class="price">${esc(s.price)}<small>${esc(s.unit)}</small></div><p>${esc(s.setup)}</p><ul class="check-list">${s.deliverables.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${button('contact?service='+encodeURIComponent(s.name),'Discuss this service')}${link(s.slug,'Explore the service ↗','text-link')}</article>`).join('')}</div></div></section><section class="section shell compact"><p class="pricing-terms"><strong>How to read these prices:</strong> they are starting points for the published scope, not promises that every environment costs the same. Software licenses, model/voice/SMS usage, custom APIs, data cleanup, compliance work, larger teams, extra locations, and additional systems are quoted separately. We agree on the actual scope before work begins.</p></section>${outcomesSection()}${faq([['Why not publish one fixed price for everything?','Because a phone agent for one location and an integration across four legacy systems are not the same project. We publish useful starting points where the scope is repeatable and quote the variables that genuinely change the work.'],['Can we combine services?','Yes. A common build combines reception or lead response with scheduling, workflow automation, and systems integration. The proposal separates one-time setup, ongoing service, and third-party usage.'],['What does custom AI cost after discovery?','The full build depends on the users, systems, data, security, integrations, reliability, and support requirements. Paid discovery produces the scope and build proposal before you commit to the larger project.']])}${cta()}`,{crumbs:[['pricing','Pricing']]});

layout('about','About Dream Protocol','Meet Dream Protocol, a founder-led AI automation company building practical voice, workflow, integration, and business AI systems for Bay Area businesses.',`${crumbs([['about','About']])}<section class="page-hero shell about-hero">${eyebrow('FOUNDER-LED. SYSTEMS-MINDED. BUILT TO SHIP.')}<h1>Less AI theater.<br><em>More working system.</em></h1><p>Dream Protocol exists for the gap between an impressive AI demo and the messy reality of a business. Calls, users, permissions, calendars, APIs, handoffs, exceptions, and follow-up all have to work together.</p></section>${founderProofSection()}<section class="section about-belief-section"><div class="shell about-belief-grid"><div>${eyebrow('WHY DREAM PROTOCOL EXISTS')}<h2>AI should do more of the work.<br><em>Not create more work.</em></h2></div><div><p>Businesses already have enough dashboards, inboxes, portals, and disconnected systems. Dream Protocol is about putting intelligence between those pieces so work moves without somebody copying, chasing, routing, or remembering every next step.</p><p>The goal is not to replace judgment. The goal is to remove repetition, make context easier to reach, and hand the unusual work to a person with the information they need.</p></div></div></section><section class="section shell about-principles-section">${heading('THE STANDARD','What we will not compromise on.','The product can evolve. The operating principles should not.')}<div class="about-principles-grid">${[['01','Show what is real','Live means live. Illustrative means illustrative. In development means exactly that.'],['02','Build around the business','The workflow, people, permissions, and existing systems come before the model choice.'],['03','Keep a human path','Exceptions, uncertainty, judgment, and sensitive situations need an explicit route back to a person.'],['04','Own the outcome','A deployment needs a measurable business result, monitoring, and a way to improve after launch.']].map(([n,h,p])=>`<article><span>${n}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></section>${credibilitySection()}${stackSection()}${platformPreviewSection()}${processSection()}${cta()}`,{active:'about',crumbs:[['about','About']]});

layout('security','AI Security & Data Handling','How Dream Protocol approaches AI data boundaries, access, human review, vendor transparency, and regulated workflows for business automation.',`${crumbs([['security','Security & data']])}<section class="page-hero shell">${eyebrow('TRUST IS PART OF THE BUILD')}<h1>Useful AI.<br><em>Controlled access.</em></h1><p>AI automation only works when the business knows what information the system can use, what it can do, and where a person takes over. We design those boundaries before launch.</p></section><section class="section shell"><div class="three-grid"><article class="feature"><span class="step-number">01</span><h2>Use the minimum data needed</h2><p>Start from the information required to perform the approved task. The public website demo uses public website information only. Production data access is scoped separately.</p></article><article class="feature"><span class="step-number">02</span><h2>Control identity and permissions</h2><p>Review accounts, roles, credentials, source permissions, and the principle of least access. Integration scope depends on the controls available in the systems involved.</p></article><article class="feature"><span class="step-number">03</span><h2>Keep sensitive decisions human</h2><p>Define the situations where AI can draft, classify, route, or recommend versus the situations where a qualified person must review or decide.</p></article></div></section><section class="section pale-section"><div class="shell">${heading('REGULATED OR SENSITIVE WORK','Assess first.<br><em>Then automate.</em>','Healthcare, financial, legal, employee, and other sensitive-data workflows require an explicit review of systems, contracts, access, retention, and operational requirements before implementation.')}<div class="three-grid"><article class="feature"><span class="step-number">04</span><h3>Vendor transparency</h3><p>Identify the model, voice, messaging, hosting, and integration providers used in the proposed workflow and review the relevant data-handling settings before launch.</p></article><article class="feature"><span class="step-number">05</span><h3>Testing and exception paths</h3><p>Test routine cases, missing information, low-confidence output, connection failure, escalation, and human fallback before production use.</p></article><article class="feature"><span class="step-number">06</span><h3>Changes stay controlled</h3><p>Document the agreed workflow and test material changes before they go live. Managed AI operations is available when the system needs ongoing review and tuning.</p></article></div></div></section>${faq([['Do you claim every Dream Protocol workflow is HIPAA, SOC 2, or otherwise compliant?','No. Compliance depends on the complete architecture, vendors, contracts, data, configuration, and client responsibilities. Regulated workflows are assessed separately before implementation.'],['Does the website AI demo use private company data?','No. The public demo is designed around public information found on the website you provide. Do not enter private customer, patient, employee, financial, or confidential information into the public demo.'],['Can we require human approval before an AI action?','Yes. Approval, escalation, and exception steps can be built into a workflow when the business process requires them.']])}${cta()}`,{crumbs:[['security','Security & data']]});

layout('contact','Talk to Dream Protocol','Show Dream Protocol the business process you want to improve. Discuss AI reception, lead response, scheduling, workflow automation, document processing, integrations, knowledge agents, or custom AI.',`${crumbs([['contact','Contact']])}<section class="page-hero shell"><div class="contact-grid"><div>${eyebrow('YOUR NEXT CHAPTER STARTS HERE')}<h1>Show us what<br><em>wastes your time.</em></h1><p>Give us the ugly workflow, the missed calls, the copy-paste process, or the system that never talks to the other system.</p><a class="email-link" href="mailto:hello@dreamprotocol.ai">hello@dreamprotocol.ai ↗</a><p class="contact-trust">Have data or security questions? ${link('security','See how we approach AI security & data ↗')}</p><div class="contact-next"><h2>What happens next</h2><ol><li>You show us the friction.</li><li>We map the AI + systems path.</li><li>You get a clear scope before anything is built.</li></ol></div></div>${read('content/partials/contact.html')}</div></section>`,{crumbs:[['contact','Contact']]});

layout('resources','Practical AI Guides for Business','Guides to AI receptionists, team training, workflow automation, and systems integration. Practical reading for your next business decision.',`${crumbs([['resources','Resources']])}<section class="page-hero shell">${eyebrow('THE DREAM PROTOCOL RESOURCE LIBRARY')}<h1>Skip the AI hype.<br><em>Build what works.</em></h1><p>Straight answers for businesses deciding what to automate, what to connect, what AI can actually handle, and what should stay human.</p></section><section class="section shell compact"><div class="guide-grid">${published.map(guideCard).join('')}</div><div class="wide-note"><h2>Start with your question.</h2><p>Not sure which guide fits your situation? Tell us what you are trying to improve and we’ll help identify a practical starting point.</p>${button('contact','Ask about your workflow',true)}</div></section>${cta()}`,{active:'resources',crumbs:[['resources','Resources']]});
for(const g of published){
 const s=services.find(s=>s.slug===g.service);
 const slug='resources/'+g.slug;
 layout(slug,g.title,g.description,`${crumbs([['resources','Resources'],[slug,g.title]])}<article><header class="page-hero shell article-hero">${eyebrow(g.category+' / PRACTICAL GUIDE')}<h1>${esc(g.title)}</h1><p>${esc(g.description)}</p><div class="article-meta"><a href="/about/">Dream Protocol</a><span>Published <time datetime="${g.publishOn}">${g.publishOn}</time></span><span>${Math.max(3,Math.ceil(g.sections.map(x=>x.join(' ')).join(' ').split(/\s+/).length/200))} min read</span></div></header><div class="shell article-layout"><aside class="article-nav"><p class="eyebrow">IN THIS GUIDE</p>${g.sections.map(([h],i)=>`<a href="#section-${i+1}">${esc(h)}</a>`).join('')}${link(s.slug,'Explore '+s.name.toLowerCase()+' ↗','text-link')}</aside><div class="article-body"><div class="takeaway">${eyebrow('THE USEFUL TAKEAWAY')}<p>${esc(g.takeaway)}</p></div>${g.sections.map(([h,p],i)=>`<section id="section-${i+1}"><h2>${esc(h)}</h2><p>${esc(p)}</p>${g.sectionSources?.[i]?.length?`<p class="source-links">Sources: ${g.sectionSources[i].map(n=>`<a href="${esc(g.sources[n].url)}" rel="noopener noreferrer">${esc(g.sources[n].title)}</a>`).join(' · ')}</p>`:''}</section>`).join('')}<section class="article-checklist"><h2>Your next-step checklist</h2><ul class="check-list">${g.checklist.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><div class="article-source">${g.sources?`<p>Researched and checked with AI on <time datetime="${esc(g.generation.sourceCheckedOn)}">${esc(g.generation.sourceCheckedOn)}</time>. Source links appear beside the sections they support. Vendor features can change; confirm availability before implementation.</p>`:''}<p>About this guide: prepared for Dream Protocol’s resource library with AI assistance. It provides general planning guidance and uses Dream Protocol’s published service scope where pricing is discussed. It is not a client case study.</p>${link('pricing','Check current scope and pricing ↗')}</div></div></div></article><section class="section shell">${heading('Put the thinking to work','Explore your next step.')}<div class="two-grid">${serviceCard(s,0)}${published.find(x=>x.slug!==g.slug)?guideCard(published.find(x=>x.slug!==g.slug)):''}</div></section>${cta()}`,{active:'resources',article:true,crumbs:[['resources','Resources'],[slug,g.title]],schema:[{'@type':'Article',headline:g.title,description:g.description,datePublished:g.publishOn,dateModified:g.updatedOn||g.publishOn,author:{'@type':'Organization',name:'Dream Protocol',url:origin+'/about/'},publisher:{'@id':origin+'/#organization'},mainEntityOfPage:origin+href(slug),image:origin+'/public/dream-protocol-abstract.webp'}]});
}
// An old generated future page cannot leak into a date-controlled build.
for(const g of guides.filter(g=>!published.includes(g))){const f=path.join(root,'resources',g.slug,'index.html');if(fs.existsSync(f))fs.unlinkSync(f);}
layout('404','Page Not Found','Find your way back to Dream Protocol’s services and resources.',`<section class="page-hero shell">${eyebrow('404 / A DIFFERENT NEXT STEP')}<h1>Let’s get you<br><em>back on track.</em></h1><p>This page could not be found. Explore our services or tell us what you’re looking for.</p><div class="actions">${button('services','Explore services')}${button('contact','Talk to us',true)}</div></section>`,{noindex:true});
fs.renameSync(path.join(root,'404/index.html'),path.join(root,'404.html'));
const sitemap=`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${pages.map(p=>`  <url><loc>${esc(p.url)}</loc></url>`).join('\n')}\n</urlset>\n`;
write('sitemap.xml',sitemap);write('public/sitemap.xml',sitemap);
const robots='User-agent: *\nAllow: /\nSitemap: https://dreamprotocol.ai/sitemap.xml\n';write('robots.txt',robots);write('public/robots.txt',robots);
write('resources/feed.xml',`<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>Dream Protocol — Practical AI Guides</title><link>${origin}/resources/</link><description>Practical AI thinking for business.</description><language>en-us</language>${published.map(g=>`<item><title>${esc(g.title)}</title><link>${origin}/resources/${g.slug}/</link><guid isPermaLink="true">${origin}/resources/${g.slug}/</guid><pubDate>${new Date(g.publishOn+'T12:00:00Z').toUTCString()}</pubDate><description>${esc(g.description)}</description></item>`).join('')}</channel></rss>`);
write('content/published.json',JSON.stringify(published.map(g=>({slug:g.slug,publishOn:g.publishOn})),null,2)+'\n');
write('.nojekyll','');
console.log(`Built ${pages.length} indexable pages; ${published.length} guides published; ${guides.length-published.length} queued. Date: ${today}`);
